import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, positionLocal, uv, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ShapeGeometry, ExtrudeGeometry, PlaneGeometry, DirectionalLight } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const ACCENT = colors.accent ?? '#ff2a38';
  const PAPER = colors.paper ?? '#e8ecf2';
  const GRAD_TOP = (colors.gradientStops && colors.gradientStops[0]?.hex) || '#1a1a22';
  const GRAD_BOT = (colors.gradientStops && colors.gradientStops[1]?.hex) || '#111116';
  const HAIRLINE = '#26262f';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (r) => items.find((i) => i.role === r);
  const quoteStr = byRole('quote')?.text ?? 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.';
  const attribStr = byRole('attribution')?.text ?? 'M. OKAFOR';
  const captionStr = byRole('caption')?.text ?? 'COLLECTOR SINCE 2019';

  const root = new Group();
  const geometries = [];
  const materials = [];

  // ---------- BACKDROP STAGE (depth plane 1) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  geometries.push(backdropGeo);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(GRAD_BOT), color(GRAD_TOP), uv().y);
  materials.push(backdropMat);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);

  // ---------- NODE-LOCAL RIM LIGHT (accent-tinted, back-left) ----------
  const rim = new DirectionalLight(ACCENT, 0.7);
  rim.position.set(-3, 1.5, -1.5);
  rim.target.position.set(0, 0, 0);
  root.add(rim);
  root.add(rim.target);

  // Cool fill from the right so the panel edge reads
  const fill = new DirectionalLight(PAPER, 0.35);
  fill.position.set(3.5, -0.5, 2.5);
  root.add(fill);

  // ---------- PANEL GROUP (depth plane 2) — everything that fades up ----------
  const panelGroup = new Group();
  root.add(panelGroup);

  const PW = 3.4;
  const PH = 1.9;
  const R = 0.06;

  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const hw = w / 2, hh = h / 2;
    s.moveTo(-hw + r, -hh);
    s.lineTo(hw - r, -hh);
    s.quadraticCurveTo(hw, -hh, hw, -hh + r);
    s.lineTo(hw, hh - r);
    s.quadraticCurveTo(hw, hh, hw - r, hh);
    s.lineTo(-hw + r, hh);
    s.quadraticCurveTo(-hw, hh, -hw, hh - r);
    s.lineTo(-hw, -hh + r);
    s.quadraticCurveTo(-hw, -hh, -hw + r, -hh);
    return s;
  }

  // hairline border plate (0.006 border)
  const borderGeo = new ShapeGeometry(roundedRectShape(PW + 0.012, PH + 0.012, R + 0.006), 12);
  geometries.push(borderGeo);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = color(HAIRLINE);
  materials.push(borderMat);
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.005);
  panelGroup.add(border);

  // panel surface — engineered vertical gradient, lit PBR
  const panelGeo = new ShapeGeometry(roundedRectShape(PW, PH, R), 12);
  geometries.push(panelGeo);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.colorNode = mix(color(GRAD_BOT), color(GRAD_TOP), smoothstep(-PH / 2, PH / 2, positionLocal.y));
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  materials.push(panelMat);
  const panel = new Mesh(panelGeo, panelMat);
  panelGroup.add(panel);

  // ---------- OVERSIZED QUOTATION MARK — extruded, accent, key-lit ----------
  function commaShape() {
    const s = new Shape();
    s.moveTo(0.0, 1.0);
    s.lineTo(0.42, 1.0);
    s.lineTo(0.42, 0.45);
    s.quadraticCurveTo(0.42, 0.0, 0.05, 0.0);
    s.lineTo(0.05, 0.18);
    s.quadraticCurveTo(0.24, 0.22, 0.26, 0.45);
    s.lineTo(0.0, 0.45);
    s.closePath();
    return s;
  }
  const markGeo = new ExtrudeGeometry([commaShape()], {
    depth: 0.055,
    bevelEnabled: true,
    bevelThickness: 0.012,
    bevelSize: 0.01,
    bevelSegments: 2,
    curveSegments: 10,
  });
  geometries.push(markGeo);
  const markMat = new MeshStandardNodeMaterial();
  markMat.color.set(ACCENT);
  markMat.roughness = 0.5;
  markMat.metalness = 0.3;
  materials.push(markMat);

  // settle wrapper for weighted-settle scale animation
  const markSettle = new Group();
  const markInner = new Group();
  const markA = new Mesh(markGeo, markMat);
  const markB = new Mesh(markGeo, markMat);
  markB.position.x = 0.56;
  markInner.add(markA);
  markInner.add(markB);
  markInner.scale.setScalar(0.62); // glyph 0.62 units tall
  markInner.position.set(-0.3, -0.31, 0); // center the pair in the settle group
  markSettle.add(markInner);
  // seated top-left, 0.5-unit padding: panel top-left inner corner (-1.2, 0.45)
  markSettle.position.set(-1.2 + 0.3, 0.45 - 0.31, 0.04);
  panelGroup.add(markSettle);

  // ---------- QUOTE TEXT (floats z +0.03) ----------
  const quoteText = ctx.fontAtlas.createText(quoteStr, {
    fontSize: 20,
    color: PAPER,
    align: 'left',
    maxWidthPx: 240,
  });
  quoteText.position.set(-1.2, -0.25, 0.03);
  panelGroup.add(quoteText);

  // ---------- ATTRIBUTION ROW: accent rule + name ----------
  const ruleGeo = new PlaneGeometry(0.2, 0.02);
  geometries.push(ruleGeo);
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.color.set(ACCENT);
  ruleMat.emissive.set(ACCENT);
  ruleMat.emissiveIntensity = 1.4; // the single brightest element on stage
  materials.push(ruleMat);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.1, -0.6, 0.03);
  panelGroup.add(rule);

  const attribText = ctx.fontAtlas.createText(attribStr, {
    fontSize: 13,
    color: PAPER,
    align: 'left',
    letterSpacingPx: 1.04,
  });
  attribText.position.set(-0.92, -0.6, 0.03);
  panelGroup.add(attribText);

  const captionText = ctx.fontAtlas.createText(captionStr, {
    fontSize: 9,
    color: '#9aa0ac',
    align: 'left',
    letterSpacingPx: 1.08,
  });
  captionText.position.set(-1.2, -0.76, 0.03);
  panelGroup.add(captionText);

  // ---------- FOREGROUND ACCENT SLIVER (depth plane 3) ----------
  const sliverGeo = new PlaneGeometry(0.5, 0.012);
  geometries.push(sliverGeo);
  const sliverMat = new MeshBasicNodeMaterial();
  sliverMat.colorNode = color(ACCENT);
  sliverMat.transparent = true;
  sliverMat.opacity = 0.8;
  materials.push(sliverMat);
  const sliver = new Mesh(sliverGeo, sliverMat);
  sliver.position.set(1.7, -1.25, 0.7);
  root.add(sliver);

  // ---------- MOUNT MOTION: fade-up panel, then weighted-settle on the mark ----------
  const fadeMats = [];
  panelGroup.traverse((o) => {
    if (o.material) {
      const list = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of list) {
        m.transparent = true;
        m.opacity = 0;
        if (fadeMats.indexOf(m) === -1) fadeMats.push(m);
      }
    }
  });

  panelGroup.position.y = 0.2;
  markSettle.scale.setScalar(1.04);

  const tl = gsap.timeline();
  tl.to(panelGroup.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(fadeMats, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(markSettle.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.5);
  // no idle motion — the piece rests with weight

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    for (const g of geometries) g.dispose();
    for (const m of materials) m.dispose();
    root.traverse((o) => {
      if (o.material) {
        const list = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of list) {
          if (materials.indexOf(m) === -1) m.dispose();
        }
      }
      if (o.geometry && geometries.indexOf(o.geometry) === -1) o.geometry.dispose();
    });
  };

  return root;
}
